import React, { forwardRef, type ReactNode } from 'react'
import { useTheme, type Style } from '@gpuix-ui/core'
import { TabsPrimitive, type Instance } from '@gpuix-ui/primitives'
import { asText } from './internal'

export const Tabs = TabsPrimitive.Root
export const TabsContent = forwardRef<Instance, Omit<TabsPrimitive.TabsContentProps, 'style'> & { style?: Style }>(function TabsContent({ style, ...props }, ref) {
  return <TabsPrimitive.Content {...props} ref={ref} style={{ paddingTop: 8, ...style }} />
})

export const TabsList = forwardRef<Instance, { children?: ReactNode; style?: Style }>(function TabsList({ style, ...props }, ref) {
  const t = useTheme()
  return (
    <TabsPrimitive.List
      {...props}
      ref={ref}
      style={{ alignItems: 'center', gap: 2, padding: 3, borderRadius: t.radius.lg, backgroundColor: t.colors.muted, alignSelf: 'flex-start', userSelect: 'none', ...style }}
    />
  )
})

export interface TabsTriggerProps extends Omit<TabsPrimitive.TabsTriggerProps, 'style' | 'children'> {
  style?: Style
  children?: ReactNode
}

export const TabsTrigger = forwardRef<Instance, TabsTriggerProps>(function TabsTrigger({ style, children, ...props }, ref) {
  const t = useTheme()
  return (
    <TabsPrimitive.Trigger
      {...props}
      ref={ref}
      style={(state) => ({
        display: 'flex',
        flexDirection: 'row',
        alignItems: 'center',
        justifyContent: 'center',
        gap: 6,
        height: 30,
        paddingLeft: 8,
        paddingRight: 8,
        borderRadius: t.radius.md,
        cursor: state.disabled ? 'default' : 'pointer',
        opacity: state.disabled ? 0.5 : 1,
        borderWidth: 1,
        borderColor: state.active && t.appearance === 'dark' ? t.colors.input : '#00000000',
        backgroundColor: state.active ? (t.appearance === 'dark' ? '#FFFFFF0B' : t.colors.background) : '#00000000',
        boxShadow: state.active ? t.shadow.sm : undefined,
        hover: state.active ? undefined : { backgroundColor: t.colors.overlay },
        ...style,
      })}
    >
      {(state) =>
        asText(children, {
          fontFamily: t.font.sans,
          fontSize: t.font.size.sm,
          fontWeight: 500,
          color: state.active ? t.colors.foreground : t.colors.mutedForeground,
          whiteSpace: 'nowrap',
        })
      }
    </TabsPrimitive.Trigger>
  )
})

/** Helpers shared by the styled components. */
import React, { useState, type ReactNode } from 'react'
import type { EventPayload } from '@gpuix/react'
import type { Style } from '@gpuix-ui/core'

/**
 * GPUI does not inherit `color`, so a bare string child would paint black.
 * Wrap string and number children in a `<text>` carrying the given style;
 * pass elements through untouched.
 */
export function asText(children: ReactNode, style: Style): ReactNode {
  if (children == null || typeof children === 'boolean') return null
  if (typeof children === 'string' || typeof children === 'number') return <text style={style}>{String(children)}</text>
  if (Array.isArray(children)) {
    if (children.every((child) => typeof child === 'string' || typeof child === 'number')) return <text style={style}>{children.join('')}</text>
    // Mixed children, like an icon next to a label: wrap just the strings.
    return children.map((child, index) =>
      typeof child === 'string' || typeof child === 'number' ? (
        <text key={`text-${index}`} style={style}>
          {String(child)}
        </text>
      ) : (
        child
      ),
    )
  }
  return children
}

/** Track native focus on an element, for a focus ring. */
export function useFocusState(handlers: { onFocus?: (event: EventPayload) => void; onBlur?: (event: EventPayload) => void } = {}) {
  const [focused, setFocused] = useState(false)
  return {
    focused,
    onFocus: (event: EventPayload) => {
      handlers.onFocus?.(event)
      setFocused(true)
    },
    onBlur: (event: EventPayload) => {
      handlers.onBlur?.(event)
      setFocused(false)
    },
  }
}

/** Track hover in React state, for components that render different children on hover. */
export function useHoverState() {
  const [hovered, setHovered] = useState(false)
  return { hovered, onMouseEnter: () => setHovered(true), onMouseLeave: () => setHovered(false) }
}
